// Water Quality Quest - Enhanced Game Logic
// Note: Functions are called from onclick handlers in HTML strings, so eslint thinks they're unused
const gameState = {currentChapter:1,trustLevel:50,dataCollected:0,ecoPoints:0,waterQuality:25,inventory:[],achievements:[],decisions:[],difficulty:1,completedChapters:[]};
const ALL_CHAPTERS=[
{number:1,title:"The Murky Beginning",story:"You arrive in Clearwater Village. The once-crystal-clear lake has turned murky brown, and dead fish float on the surface. Worried villagers gather at the shore. As the new Eco-Ranger, you need to find out what's wrong with the water.",mission:"Test water samples from 3 different locations to find clues about the pollution.",difficulty:1,minigame:"waterTesting",learningGoal:"Learn how pH, temperature, and turbidity tell us about water health.",rewards:{ecoPoints:100,trust:10,items:["pH Strips","Thermometer","Eco Journal"]}},
{number:2,title:"Ripples of Doubt",story:"The villagers are arguing! Farmer Joe says the old factory is dumping chemicals. Factory manager Sarah blames farm fertilizers. Mayor Chen wants answers fast, but you know rushing could mean missing important clues. Who should you trust?",mission:"Interview 3 villagers and compare their stories. Use your detective skills to find the truth!",difficulty:2,minigame:"investigation",learningGoal:"Learn why we need multiple sources of data and how to spot bias.",rewards:{ecoPoints:150,trust:15,items:["Field Notebook","Sample Vials"]}},
{number:3,title:"Tools of the Trade",story:"Dr. Marina Chen, a retired scientist, invites you to her lab. 'These digital sensors can detect pollution humans can't see,' she explains, handing you a sleek probe. 'But remember - technology is only as good as the person using it. Let me teach you.'",mission:"Complete the sensor training course. Learn to read digital data and compare it with manual tests.",difficulty:2,minigame:"techTraining",learningGoal:"Discover how modern technology helps us monitor water quality more accurately.",rewards:{ecoPoints:200,trust:10,items:["Digital Probe","Drone","Tech Explorer Badge"]}},
{number:4,title:"Upstream Mystery",story:"Following the river upstream, you discover a strange rainbow-colored film on the water near the forest. Is it oil from the factory? Natural plant oils? Or something else? You need to trace where it's coming from.",mission:"Use your drone to map the pollution flow. Collect samples along the way.",difficulty:3,minigame:"mapping",learningGoal:"Learn how pollution travels through water systems.",rewards:{ecoPoints:250,trust:20,items:["GPS Tracker","Microplastic Kit"]}},
{number:5,title:"The Factory's Secret",story:"A rusty gate blocks the old factory entrance. Through the fence, you spot a pipe still dripping dark liquid into the river. The factory claims it's been shut down for years. You need proof.",mission:"Sneak past security (carefully!) and photograph the illegal discharge. Collect a water sample.",difficulty:3,minigame:"stealth",learningGoal:"Understand industrial pollution and why environmental laws matter.",rewards:{ecoPoints:300,trust:25,items:["Camera","Chemical Test Kit"]}},
{number:6,title:"The Farmer's Dilemma",story:"Farmer Joe shows you his fields. 'I need fertilizers to feed my family,' he says. 'But I don't want to hurt the water.' You see nutrient-rich runoff flowing into the stream after rain. Can you help him farm sustainably?",mission:"Design a nutrient management plan. Test different fertilizer amounts and see their impact on water quality.",difficulty:4,minigame:"farming",learningGoal:"Learn about nitrogen cycles, eutrophication, and how farm runoff affects water ecosystems.",rewards:{ecoPoints:350,trust:30,items:["Soil Test Kit","Nutrient Guide"]}},
{number:7,title:"The Urban Drain",story:"Dark clouds gather. Rain starts pouring. The city's storm drains overflow with oil, trash, and chemicals washing off streets. You have 5 minutes before the contaminated water reaches the lake!",mission:"Race against time! Deploy barriers and collect samples before the pollution spreads.",difficulty:4,minigame:"timedChallenge",learningGoal:"Understand urban runoff, combined sewer overflows, and why cities need green infrastructure.",rewards:{ecoPoints:400,trust:20,items:["Rain Collector","Urban Map"]}},
{number:8,title:"The Citizen Scientist",story:"Local students want to help! Emma (age 12) asks, 'Can we test the water too?' You organize a training session. Teaching others multiplies your impact - but they need to learn to do it safely and accurately.",mission:"Train 3 student volunteers. Review their test results and teach them proper sampling techniques.",difficulty:3,minigame:"training",learningGoal:"Discover how citizen science empowers communities and creates large-scale environmental monitoring networks.",rewards:{ecoPoints:450,trust:35,items:["Training Manual","Team Badge"]}},
{number:9,title:"Cloudy Waters",story:"After testing rainwater, you're shocked. pH 4.2 - that's as acidic as orange juice! The rain itself is polluted. You trace it to a coal plant 50 miles away. Air pollution is becoming water pollution.",mission:"Collect rain samples from 5 locations. Map the acid rain pattern and identify the source.",difficulty:5,minigame:"acidRain",learningGoal:"Learn how air pollution creates acid rain, affecting forests, lakes, and buildings hundreds of miles away.",rewards:{ecoPoints:500,trust:25,items:["pH Meter Pro","Air Quality Sensor"]}},
{number:10,title:"The Council of Waters",story:"The village council meeting is packed. Factory owner Mr. Chen denies everything. Farmer Joe is defensive. Mayor Rodriguez needs proof. You have 10 minutes to present your data. Can you convince them?",mission:"Create a compelling presentation using your data. Choose the right charts and arguments to persuade the council.",difficulty:5,minigame:"presentation",learningGoal:"Master science communication - how to present data clearly to non-scientists and influence policy decisions.",rewards:{ecoPoints:600,trust:40,items:["Presentation Kit","Funding Grant"]}},
{number:11,title:"The River of Decisions",story:"Three tributaries feed the main river. North Fork: factory pollution (high toxins). East Branch: farm runoff (high nutrients). South Stream: microplastics. You only have budget to fix ONE. Which do you choose?",mission:"Analyze each tributary's impact. Make a strategic decision and defend your choice.",difficulty:6,minigame:"strategy",learningGoal:"Explore systems thinking, environmental triage, and the difficult trade-offs in real-world conservation.",rewards:{ecoPoints:700,trust:30,items:["Satellite Access","Decision Matrix"]}},
{number:12,title:"The Lake of Memories",story:"Mrs. Garcia, 87, shows you a photo from 1960. The lake sparkles crystal-clear, children swimming. 'It was paradise,' she whispers. Can you restore it to what it was?",mission:"Compare historical photos with current data. Identify what changed and create a restoration timeline.",difficulty:5,minigame:"timeline",learningGoal:"Understand environmental baselines, historical ecology, and why long-term data matters for restoration.",rewards:{ecoPoints:750,trust:35,items:["Historical Archive","Historian Badge"]}},
{number:13,title:"The Hidden Mine",story:"An abandoned copper mine from the 1800s still leaks. You descend into darkness with your headlamp. Rusty equipment everywhere. Orange water drips from the walls - heavy metals. Your oxygen meter beeps a warning.",mission:"Navigate the mine safely. Collect groundwater samples from 3 depths. Identify contamination levels.",difficulty:7,minigame:"mining",learningGoal:"Learn about heavy metal contamination, acid mine drainage, and groundwater hydrology.",rewards:{ecoPoints:800,trust:25,items:["Spectrometer","Safety Gear","Headlamp"]}},
{number:14,title:"Invisible Invaders",story:"Under the microscope, you gasp. Thousands of tiny plastic fibers in every water sample. From washing machines, car tires, synthetic clothes. They're everywhere - and they're entering the food chain.",mission:"Use the digital microscope to count microplastics. Trace them to their sources in the community.",difficulty:6,minigame:"microscopy",learningGoal:"Understand microplastic pollution, bioaccumulation, and the circular economy needed to solve it.",rewards:{ecoPoints:850,trust:30,items:["Digital Microscope","Plastic Guide"]}},
{number:15,title:"The Algae Bloom",story:"EMERGENCY! The lake turned bright green overnight. Fish are dying - suffocating. The algae bloom is consuming all the oxygen. You have hours, not days, to save the ecosystem.",mission:"Deploy emergency oxygenators. Calculate nutrient levels. Stop the bloom before total collapse.",difficulty:8,minigame:"crisis",learningGoal:"Learn about eutrophication, algal blooms, dead zones, and emergency aquatic ecosystem management.",rewards:{ecoPoints:900,trust:40,items:["Oxygenator","BOD Meter","Crisis Kit"]}},
{number:16,title:"Wells of Worry",story:"The contamination reached the drinking water wells. Panic spreads. Parents won't let kids drink tap water. The mayor calls an emergency. You need to find clean water sources NOW.",mission:"Test 10 wells at different depths. Map the contamination plume. Find safe water sources.",difficulty:7,minigame:"wellTesting",learningGoal:"Understand groundwater flow, aquifer contamination, and how pollution moves underground.",rewards:{ecoPoints:1000,trust:45,items:["Well Drill","Filtration System","Aquifer Map"]}},
{number:17,title:"The Rain Experiment",story:"You build a rooftop laboratory. Rain collectors at different heights. Sensors measuring every drop. Over 30 days, you'll track how air pollution becomes water pollution in real-time.",difficulty:6,minigame:"experiment",learningGoal:"Design scientific experiments, control variables, and connect atmospheric chemistry to water quality.",rewards:{ecoPoints:1100,trust:30,items:["Rain Collector Pro","Data Logger","Weather Station"]}},
{number:18,title:"Voices of the Forest",story:"The wetland birds are sick. Frogs have deformities. Otters are disappearing. Dr. Chen explains bioaccumulation: toxins concentrate as they move up the food chain. The top predators suffer most.",mission:"Track wildlife health. Test tissue samples. Map the contamination through the food web.",difficulty:7,minigame:"ecology",learningGoal:"Learn about biomagnification, food webs, indicator species, and ecosystem health monitoring.",rewards:{ecoPoints:1200,trust:35,items:["Wildlife Camera","Biodiversity Map","Tissue Sampler"]}},
{number:19,title:"The Night of Fire and Water",story:"3 AM. Lightning strikes the factory. Fire! Chemicals explode. Toxic foam rushes toward the river. The storm makes it worse. You coordinate emergency response in the chaos.",mission:"Deploy containment booms. Alert downstream communities. Monitor toxin levels in real-time.",difficulty:9,minigame:"emergency",learningGoal:"Master emergency environmental response, risk assessment, and crisis communication under pressure.",rewards:{ecoPoints:1400,trust:50,items:["Emergency Kit","Alert System","Containment Booms"]}},
{number:20,title:"Turning the Tide",story:"500 volunteers show up for Clean Water Day! News cameras everywhere. You organize teams, assign zones, track progress. By sunset, you've removed 2 tons of trash. The community is united.",mission:"Manage volunteer logistics. Categorize collected waste. Create an impact report for the media.",difficulty:7,minigame:"logistics",learningGoal:"Learn community organizing, volunteer management, and how collective action creates change.",rewards:{ecoPoints:1600,trust:55,items:["Leadership Badge","Media Kit","Volunteer Coordinator"]}},
{number:21,title:"Blueprints for Hope",story:"With the council's funding, you design a restoration plan. Reed beds for natural filtration. Retention ponds to slow runoff. Native plants to stabilize banks. It's engineering meets ecology.",mission:"Design your restoration system. Balance costs, effectiveness, and ecological benefits.",difficulty:8,minigame:"design",learningGoal:"Apply ecological engineering, green infrastructure, and nature-based solutions to water problems.",rewards:{ecoPoints:1800,trust:40,items:["Design Software","Blueprint Kit","CAD Tools"]}},
{number:22,title:"Engineering the Flow",story:"Construction begins! You build a bio-filtration system using gravel, sand, and beneficial bacteria. Water flows through layers, each removing different pollutants. It's like a giant kidney for the river.",mission:"Optimize filter layers. Test flow rates. Measure removal efficiency for different pollutants.",difficulty:8,minigame:"engineering",learningGoal:"Understand filtration physics, bioremediation, and how natural processes can clean water.",rewards:{ecoPoints:2000,trust:45,items:["Eco Engineer Badge","Filter Designs","Flow Meter"]}},
{number:23,title:"The Budget Battle",story:"The council gives you $100,000. New sensors cost $40K. Education programs $30K. Legal action against polluters $50K. You can't afford everything. What's most important?",mission:"Allocate your budget wisely. Each choice has long-term consequences. Justify your decisions.",difficulty:9,minigame:"budget",learningGoal:"Explore environmental economics, cost-benefit analysis, and resource allocation in conservation.",rewards:{ecoPoints:2200,trust:35,items:["Budget Tool","Economic Report","Grant Writer"]}},
{number:24,title:"The River Tribunal",story:"The courtroom is tense. Corporate lawyers attack your data. 'Correlation isn't causation!' they argue. You must defend your science, cross-examine witnesses, and prove the pollution link.",mission:"Present evidence. Counter legal arguments. Use your data to prove causation, not just correlation.",difficulty:10,minigame:"debate",learningGoal:"Learn environmental law, burden of proof, and how science intersects with legal systems.",rewards:{ecoPoints:2500,trust:60,items:["Legal Brief","Advocate Badge","Expert Witness Certification"]}},
{number:25,title:"Healing Waters Festival",story:"Celebration time! The water quality improved 40%. You create interactive exhibits: kids test water samples, adults learn about watersheds. Solar panels power everything. It's education through joy.",mission:"Design 5 educational exhibits. Make complex science accessible and fun for all ages.",difficulty:7,minigame:"education",learningGoal:"Master environmental education, public engagement, and how to inspire the next generation.",rewards:{ecoPoints:2800,trust:50,items:["Festival Badge","Education Kit","Exhibit Designs"]}},
{number:26,title:"Satellite Eyes",story:"NASA grants you satellite data access! Suddenly you see pollution patterns across entire continents. Your local problem connects to global systems. You join a worldwide network of water guardians.",mission:"Analyze satellite imagery. Identify pollution sources from space. Collaborate with international teams.",difficulty:9,minigame:"satellite",learningGoal:"Learn remote sensing, GIS mapping, and how global environmental monitoring works.",rewards:{ecoPoints:3200,trust:45,items:["GIS Software","Satellite Access","Global Network"]}},
{number:27,title:"The Great Drought",story:"Climate change hits hard. The river shrinks to a trickle. Farmers need water. Cities need water. Fish need water. Everyone's desperate. You must allocate scarce resources without anyone dying.",mission:"Manage water distribution during crisis. Balance human needs with ecosystem survival.",difficulty:10,minigame:"drought",learningGoal:"Understand climate resilience, water scarcity, and the ethics of resource allocation.",rewards:{ecoPoints:3600,trust:40,items:["Resource Manager","Climate Data","Drought Monitor"]}},
{number:28,title:"Allies from Afar",story:"You video call with Eco-Rangers from Kenya, Brazil, and India. They face similar challenges. You share data, strategies, solutions. Together, you're stronger than alone.",mission:"Participate in global data exchange. Learn from international case studies. Contribute your findings.",difficulty:8,minigame:"collaboration",learningGoal:"Embrace global cooperation, cultural perspectives, and international environmental solidarity.",rewards:{ecoPoints:4000,trust:55,items:["Global Ranger Badge","Translation Tools","Data Exchange Platform"]}},
{number:29,title:"The Global Summit",story:"United Nations Headquarters, New York. World leaders listen as you present Clearwater Village's success story. Your local work becomes a global model. The pressure is immense.",mission:"Deliver a 10-minute presentation to world leaders. Answer tough questions. Influence global water policy.",difficulty:10,minigame:"summit",learningGoal:"Learn international diplomacy, policy influence, and how local action scales to global impact.",rewards:{ecoPoints:4500,trust:70,items:["UN Badge","Global Accord","Diplomat Certification"]}},
{number:30,title:"The Flow of the Future",story:"50 years pass in simulation. You see the results of every decision you made. Some lakes thrive with fish and birds. Others struggle. Climate change adds new challenges. Your legacy unfolds.",mission:"Watch your long-term impact. Reflect on successes and failures. Understand that environmental work never truly ends.",difficulty:10,minigame:"simulation",learningGoal:"Reflect on legacy, long-term thinking, and personal responsibility in environmental stewardship.",rewards:{ecoPoints:5000,trust:100,items:["Master Ranger Badge","Legacy Report","Time Capsule"]}}
];
function initGame(){loadChapter(gameState.currentChapter);updateStats()}
function updateStats(){document.getElementById('trustLevel').textContent=gameState.trustLevel;document.getElementById('dataCollected').textContent=gameState.dataCollected;document.getElementById('ecoPoints').textContent=gameState.ecoPoints;document.getElementById('waterQuality').textContent=gameState.waterQuality+'%';const progress=(gameState.currentChapter/ALL_CHAPTERS.length)*100;document.getElementById('progressBar').style.width=progress+'%';document.getElementById('progressText').textContent=`Chapter ${gameState.currentChapter} of ${ALL_CHAPTERS.length}`}
function loadChapter(n){const c=ALL_CHAPTERS[n-1];if(!c)return showGameComplete();document.getElementById('gameContent').innerHTML=`<div class="chapter-card"><div class="chapter-header"><h2 class="chapter-title">${c.title}</h2><div class="chapter-number">Chapter ${c.number}</div></div><div class="story-text">${c.story}</div><div class="mission-box"><h3>🎯 Your Mission</h3><p>${c.mission}</p><p><strong>Difficulty:</strong> ${'⭐'.repeat(c.difficulty)}</p></div><div id="minigameContainer"></div><div class="learning-goal"><h4>💡 Learning Goal</h4><p>${c.learningGoal}</p></div></div><div class="inventory"><h3>🎒 Your Equipment</h3><div class="inventory-grid" id="inventoryGrid"></div></div>`;updateInventory();startMinigame(c.minigame,c.number)}
function startMinigame(t,n){const c=document.getElementById('minigameContainer');
if(t==='waterTesting')loadWaterTestingGame(c);
else if(t==='investigation')loadInvestigationGame(c);
else if(t==='techTraining')loadTechTrainingGame(c);
else if(t==='mapping')loadMappingGame(c);
else if(t==='stealth')loadStealthGame(c);
else if(t==='farming')loadFarmingGame(c);
else if(t==='timedChallenge')loadTimedChallenge(c);
else if(t==='training')loadTrainingGame(c);
else if(t==='acidRain')loadAcidRainGame(c);
else if(t==='presentation')loadPresentationGame(c);
else if(t==='strategy')loadStrategyGame(c);
else if(t==='timeline')loadTimelineGame(c);
else if(t==='mining')loadMiningGame(c);
else if(t==='microscopy')loadMicroscopyGame(c);
else if(t==='crisis')loadCrisisGame(c);
else if(t==='wellTesting')loadWellTestingGame(c);
else if(t==='experiment')loadExperimentGame(c);
else if(t==='ecology')loadEcologyGame(c);
else if(t==='emergency')loadEmergencyGame(c);
else if(t==='logistics')loadLogisticsGame(c);
else if(t==='design')loadDesignGame(c);
else if(t==='engineering')loadEngineeringGame(c);
else if(t==='budget')loadBudgetGame(c);
else if(t==='debate')loadDebateGame(c);
else if(t==='education')loadEducationGame(c);
else if(t==='satellite')loadSatelliteGame(c);
else if(t==='drought')loadDroughtGame(c);
else if(t==='collaboration')loadCollaborationGame(c);
else if(t==='summit')loadSummitGame(c);
else if(t==='simulation')loadSimulationGame(c);
else loadGenericChallenge(c,n)}
function loadWaterTestingGame(c){c.innerHTML='<div class="mini-game-container"><h4>Water Sample Analysis</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 What You\'ll Learn:</h4><p><strong>pH (0-14 scale):</strong> Healthy water = 6.5-8.5. Too acidic (&lt;6.5) or alkaline (&gt;8.5) harms aquatic life.</p><p><strong>Temperature:</strong> Healthy = 10-20°C. High temps (&gt;25°C) reduce oxygen, stress fish.</p><p><strong>Turbidity (NTU):</strong> Healthy = &lt;10 NTU. High turbidity blocks sunlight, clogs fish gills.</p></div><div id="gamePhase"></div></div>';showOneByOneTesting()}
let selectedTools=[];let selectedSamples=[];let testingPhase='tools';let testedSources=[];let foundBiggestPolluter=false;
function showToolSelection(){document.getElementById('gamePhase').innerHTML='<h4>Step 1: Select Your Testing Equipment</h4><p><strong>Instructions:</strong> Choose 3 tools to measure pH, Temperature, and Turbidity. Click on each tool to learn what it does!</p><div class="sample-grid"><div class="sample-card" onclick="selectTool(\'phStrips\',this)"><div class="icon">🧪</div><div class="label">pH Strips</div></div><div class="sample-card" onclick="selectTool(\'thermometer\',this)"><div class="icon">🌡️</div><div class="label">Thermometer</div></div><div class="sample-card" onclick="selectTool(\'turbidityMeter\',this)"><div class="icon">💡</div><div class="label">Turbidity Meter</div></div><div class="sample-card" onclick="selectTool(\'microscope\',this)"><div class="icon">🔬</div><div class="label">Microscope</div></div><div class="sample-card" onclick="selectTool(\'scale\',this)"><div class="icon">⚖️</div><div class="label">Weight Scale</div></div><div class="sample-card" onclick="selectTool(\'ruler\',this)"><div class="icon">📏</div><div class="label">Ruler</div></div></div><div id="toolFeedback"></div><button class="btn btn-success" id="toolsBtn" onclick="checkTools()" disabled>Confirm Tools</button>'}
function selectTool(tool,el){const toolInfo={phStrips:'✅ CORRECT! pH strips measure acidity/alkalinity (0-14 scale). Essential for water testing!',thermometer:'✅ CORRECT! Thermometers measure water temperature. High temps reduce oxygen and stress fish.',turbidityMeter:'✅ CORRECT! Turbidity meters measure cloudiness (NTU). High turbidity blocks sunlight and indicates pollution.',microscope:'❌ WRONG TOOL! Microscopes view tiny organisms and microplastics. Useful, but not for basic water quality parameters (pH, temp, turbidity).',scale:'❌ WRONG TOOL! Scales measure weight/mass. Not useful for testing water quality parameters.',ruler:'❌ WRONG TOOL! Rulers measure length/distance. Not useful for water quality testing.'};const correct=['phStrips','thermometer','turbidityMeter'];if(selectedTools.includes(tool)){selectedTools=selectedTools.filter(t=>t!==tool);el.classList.remove('selected');el.querySelector('.tool-feedback')?.remove()}else if(selectedTools.length<3){selectedTools.push(tool);el.classList.add('selected');const feedbackDiv=document.createElement('div');feedbackDiv.className='tool-feedback';feedbackDiv.style.cssText='font-size:11px;margin-top:5px;padding:5px;background:'+(correct.includes(tool)?'#d4edda':'#fff3cd')+';border-radius:4px;border-left:4px solid '+(correct.includes(tool)?'#28a745':'#ffc107');feedbackDiv.innerHTML=toolInfo[tool];el.appendChild(feedbackDiv);if(!correct.includes(tool)){gameState.ecoPoints=Math.max(0,gameState.ecoPoints-10);updateStats();showAchievement('⚠️ Wrong Tool!','You lost 10 points. Read what each tool does!')}}document.getElementById('toolsBtn').disabled=selectedTools.length!==3}
function checkTools(){const correct=['phStrips','thermometer','turbidityMeter'];const allCorrect=selectedTools.every(t=>correct.includes(t));if(allCorrect){document.getElementById('toolFeedback').innerHTML='<div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><h4 style="margin-top:0">✅ Perfect Equipment Selection!</h4><p>You chose the right tools for water quality testing. Now let us collect samples!</p></div>';gameState.ecoPoints+=50;updateStats();setTimeout(showOneByOneTesting,1500)}else{document.getElementById('toolFeedback').innerHTML='<div class="learning-box" style="background:#ffebee;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #e74c3c"><h4 style="margin-top:0">❌ Incorrect Tools Selected!</h4><p>You need: <strong>pH Strips</strong> (acidity), <strong>Thermometer</strong> (temperature), and <strong>Turbidity Meter</strong> (cloudiness).</p><p>Try again! Deselect wrong tools and choose the correct ones.</p></div>';selectedTools=[];document.querySelectorAll('.sample-card').forEach(card=>card.classList.remove('selected'));document.querySelectorAll('.tool-feedback').forEach(fb=>fb.remove());document.getElementById('toolsBtn').disabled=true}}
function showOneByOneTesting(){document.getElementById('gamePhase').innerHTML='<h4>🔬 Test Water Sources One at a Time</h4><p><strong>Instructions:</strong> Select ONE source to test. Learn about each pollution source until you find the biggest polluter!</p><div id="testedSourcesList"></div><div class="sample-grid" id="sourceGrid"></div><div id="testResults"></div>';renderSourceGrid()}
function renderSourceGrid(){const sources=[{id:'lake',icon:'🏞️',label:'Lake Shore'},{id:'river',icon:'🌊',label:'River Inlet'},{id:'factory',icon:'🏭',label:'Factory Drain'},{id:'farm',icon:'🚜',label:'Farm Runoff'},{id:'well',icon:'⛲',label:'Village Well'},{id:'forest',icon:'🌲',label:'Forest Stream'}];let html='';sources.forEach(s=>{const tested=testedSources.includes(s.id);const disabled=tested?'opacity:0.5;pointer-events:none;':'';html+=`<div class="sample-card" style="${disabled}" onclick="testSingleSource('${s.id}',this)"><div class="icon">${s.icon}</div><div class="label">${s.label}</div>${tested?'<div style="font-size:10px;color:#28a745">✅ Tested</div>':''}</div>`});document.getElementById('sourceGrid').innerHTML=html;updateTestedList()}
function updateTestedList(){if(testedSources.length===0)return;let html='<div class="learning-box" style="background:#f0f0f0;padding:10px;margin:10px 0"><strong>Sources Tested:</strong> '+testedSources.length+'/6';if(foundBiggestPolluter){html+=' | <span style="color:#28a745">✅ Biggest polluter found!</span>'}html+='</div>';document.getElementById('testedSourcesList').innerHTML=html}
function testSingleSource(source,el){if(testedSources.includes(source))return;testedSources.push(source);const data={lake:{ph:6.5,temp:22,turbidity:45,status:'warning',isBiggest:false,education:'<strong>Lake Shore - Moderate Pollution</strong><br>pH: 6.5 (slightly acidic), Temp: 22°C (warm), Turbidity: 45 NTU (cloudy)<br><br>📚 <strong>What this means:</strong> The lake is showing signs of pollution. The slightly acidic pH and high turbidity suggest contamination, but this is likely a <em>result</em> of pollution flowing in from elsewhere, not the source itself.<br><br>💡 <strong>Why it\'s not the biggest polluter:</strong> Lakes are often victims of upstream pollution. Keep testing to find where the pollution is coming from!'},river:{ph:7.2,temp:18,turbidity:15,status:'good',isBiggest:false,education:'<strong>River Inlet - Acceptable Quality</strong><br>pH: 7.2 (normal), Temp: 18°C (cool), Turbidity: 15 NTU (slightly cloudy)<br><br>📚 <strong>What this means:</strong> The river water is relatively healthy! The pH is in the normal range, temperature is good for fish, and turbidity is acceptable.<br><br>💡 <strong>Why it\'s not the biggest polluter:</strong> This water is cleaner than the lake, which means the pollution is entering downstream. The river is bringing in relatively clean water.'},factory:{ph:4.8,temp:28,turbidity:85,status:'danger',isBiggest:true,education:'<strong>🚨 Factory Drain - SEVERE POLLUTION!</strong><br>pH: 4.8 (HIGHLY ACIDIC - like orange juice!), Temp: 28°C (very hot), Turbidity: 85 NTU (extremely cloudy)<br><br>📚 <strong>What this means:</strong><ul style="text-align:left;margin:10px 0"><li><strong>pH 4.8:</strong> Extremely acidic! This dissolves fish scales, kills eggs, and damages gills. Healthy water = 6.5-8.5</li><li><strong>28°C:</strong> Too hot! Reduces oxygen levels and causes thermal stress to aquatic life. Healthy = 10-20°C</li><li><strong>85 NTU:</strong> Extremely cloudy! Blocks sunlight (killing plants), clogs fish gills, and carries toxins. Healthy = &lt;10 NTU</li></ul><br>🎯 <strong>THIS IS THE BIGGEST POLLUTER!</strong> The factory is illegally dumping acidic chemicals and hot wastewater directly into the water system. This is the primary source killing aquatic life!'},farm:{ph:8.5,temp:20,turbidity:55,status:'warning',isBiggest:false,education:'<strong>Farm Runoff - Nutrient Pollution</strong><br>pH: 8.5 (too alkaline), Temp: 20°C (moderate), Turbidity: 55 NTU (very cloudy)<br><br>📚 <strong>What this means:</strong> Farm fertilizers are washing into the water, making it too alkaline (high pH). The high turbidity shows soil erosion and nutrient runoff.<br><br>💡 <strong>Why it\'s a problem but not the biggest:</strong> Fertilizer runoff causes eutrophication (algae blooms) which depletes oxygen. This is serious, but the extreme acidity and heat from the factory is more immediately deadly to fish. Both need to be addressed!'},well:{ph:7.0,temp:16,turbidity:5,status:'good',isBiggest:false,education:'<strong>Village Well - Safe Drinking Water</strong><br>pH: 7.0 (neutral - perfect!), Temp: 16°C (cool), Turbidity: 5 NTU (crystal clear)<br><br>📚 <strong>What this means:</strong> Excellent news! The village well is still clean and safe for drinking. The groundwater hasn\'t been contaminated yet.<br><br>💡 <strong>Why this matters:</strong> Wells draw from underground aquifers which filter water naturally. This shows the pollution is surface water contamination, not groundwater (yet). We need to stop the pollution before it seeps underground!'},forest:{ph:7.4,temp:14,turbidity:8,status:'good',isBiggest:false,education:'<strong>Forest Stream - Pristine Natural Water</strong><br>pH: 7.4 (slightly alkaline - natural), Temp: 14°C (cold), Turbidity: 8 NTU (very clear)<br><br>📚 <strong>What this means:</strong> This is what healthy water looks like! The forest stream is untouched by pollution. Trees and plants naturally filter the water, keeping it clean.<br><br>💡 <strong>Environmental lesson:</strong> Forests are nature\'s water purifiers. The roots prevent erosion, plants absorb excess nutrients, and the shade keeps water cool. Protecting forests = protecting water quality!'}};const result=data[source];let html='<div class="data-chart" style="margin:20px 0;padding:20px;background:'+(result.status==='danger'?'#ffebee':result.status==='warning'?'#fff3cd':'#d4edda')+';border-radius:8px;border-left:4px solid '+(result.status==='danger'?'#e74c3c':result.status==='warning'?'#ffc107':'#28a745')+'"><div style="font-size:14px;line-height:1.6">'+result.education+'</div></div>';if(result.isBiggest){html+='<div class="learning-box" style="background:#d4edda;padding:15px;margin:15px 0;border-radius:8px;border-left:4px solid #28a745"><h4 style="margin-top:0">🎉 Congratulations!</h4><p>You found the biggest pollution source! You can now:</p><ul style="text-align:left"><li>✅ Test other sources to learn more (optional)</li><li>✅ Proceed to the next chapter when ready</li></ul></div>';foundBiggestPolluter=true;gameState.ecoPoints+=100;updateStats();html+='<button class="btn btn-success" onclick="completeChapter()" style="margin:10px 5px">🎯 Proceed to Next Chapter</button>';if(testedSources.length<6){html+='<button class="btn btn-secondary" onclick="document.getElementById(\'testResults\').innerHTML=\'\'" style="margin:10px 5px">🔬 Test Another Source</button>'}}else{html+='<button class="btn btn-primary" onclick="document.getElementById(\'testResults\').innerHTML=\'\';renderSourceGrid()" style="margin:10px">🔬 Test Another Source</button>'}document.getElementById('testResults').innerHTML=html;renderSourceGrid()}
function analyzeSamples(){/* Legacy function - no longer used in one-by-one testing */}
function loadInvestigationGame(c){c.innerHTML='<div class="mini-game-container"><h4>🕵️ Village Investigation</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Multiple Data Sources & Bias</h4><p><strong>Why we need multiple sources:</strong> One person\'s story might be incomplete or biased. Scientists gather data from many sources to find the truth.</p><p><strong>Avoiding bias:</strong> Everyone has their own perspective. Farmers, factory owners, and residents all see the problem differently. Your job: stay objective and collect ALL viewpoints.</p></div><p><strong>Instructions:</strong> Interview 3 different villagers. Choose respectful, scientific responses to build trust!</p><p style="margin:10px 0;padding:10px;background:#fff3cd;border-radius:5px;border-left:4px solid #ffc107;">💡 <strong>Tip:</strong> Being respectful and scientific usually works better than accusing people!</p><div id="interviewArea"></div><div id="investigationResult"></div></div>';showNextInterview()}
let interviewCount=0;
const interviews=[{name:'Farmer Joe',avatar:'👨‍🌾',text:'"I\'ve been farming here for 30 years. Yes, I use fertilizers - everyone does! But that factory upstream? They dump chemicals every night. I\'ve seen the trucks."',choices:[{text:'❌ Accuse: "Your fertilizers are poisoning the water!"',trust:-10},{text:'✅ Ask Politely: "Can you show me your fertilizer records? I want to understand the full picture."',trust:15},{text:'🔬 Suggest Testing: "Let\'s test the soil runoff together. Science will show us the truth."',trust:10}]},{name:'Factory Manager',avatar:'👔',text:'"Our facility meets all EPA standards! We have permits for everything. Those farmers use way more chemicals than we do. Check THEIR records!"',choices:[{text:'❌ Threaten: "I\'ll report you to the EPA!"',trust:-10},{text:'✅ Request Data: "May I see your discharge permits and water test results?"',trust:15},{text:'🔬 Propose Monitoring: "Can we install sensors at your outflow pipe?"',trust:10}]},{name:'Village Elder',avatar:'👵',text:'"The river was crystal clear when I was young. The factory came in 1975, farms expanded in the 80s. Both changed things. But the worst die-offs happen after factory night shifts."',choices:[{text:'❌ Ignore: "That\'s just your opinion, not science."',trust:-10},{text:'✅ Value Wisdom: "Your historical perspective is valuable data. Can you show me old photos?"',trust:15},{text:'🔬 Correlate: "Let\'s match die-off dates with factory shift schedules and farm seasons."',trust:10}]}];
function showNextInterview(){if(interviewCount>=interviews.length){document.getElementById('investigationResult').innerHTML='<div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><h4 style="margin-top:0">✅ Investigation Complete!</h4><p><strong>Multiple perspectives collected:</strong> Farmer blames factory. Factory blames farmers. Elder provides historical context.</p><p><strong>Scientific approach:</strong> You gathered ALL viewpoints without bias. Now you can test each claim with data!</p><p><strong>Key lesson:</strong> Truth emerges from combining multiple sources, not believing just one person.</p></div><button class="btn btn-success" onclick="completeChapter()">Analyze All Evidence</button>';return}const interview=interviews[interviewCount];document.getElementById('interviewArea').innerHTML=`<div class="dialogue-box"><div class="dialogue-character"><div class="character-avatar">${interview.avatar}</div><div class="character-name">${interview.name}</div></div><div class="dialogue-text">${interview.text}</div><div class="choice-buttons">${interview.choices.map((choice,i)=>`<div class="choice-btn" onclick="makeChoice(${choice.trust},${i})">${choice.text}</div>`).join('')}</div></div>`}
function makeChoice(tc,choiceIdx){gameState.trustLevel+=tc;gameState.decisions.push(choiceIdx);updateStats();const feedback=tc>0?'🤝 Good approach! Trust increased.':'⚠️ That approach hurt trust.';document.getElementById('interviewArea').innerHTML+=`<div class="test-result ${tc>0?'good':'warning'}" style="margin:10px 0"><strong>${feedback}</strong> Trust ${tc>0?'+':''} ${tc} points</div>`;interviewCount++;setTimeout(showNextInterview,1000)}
function loadTechTrainingGame(c){c.innerHTML='<div class="mini-game-container"><h4>Digital Sensor Training</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Modern Technology in Environmental Monitoring</h4><p><strong>Digital sensors vs. manual testing:</strong> Digital probes give instant, precise readings. Manual tests (pH strips) are cheaper but less accurate.</p><p><strong>Why accuracy matters:</strong> Small changes (pH 7.0 → 6.5) can signal big problems. Digital sensors detect pollution humans can\'t see.</p></div><div class="data-chart"><h4>📊 Live Sensor Readings</h4><div class="chart-bar"><div class="chart-label">pH Level</div><div class="chart-bar-fill"><div class="chart-bar-value" style="width:72%">7.2 ✅ Normal</div></div></div><div class="chart-bar"><div class="chart-label">Dissolved O₂</div><div class="chart-bar-fill"><div class="chart-bar-value" style="width:85%">8.5 mg/L ✅ Healthy</div></div></div><div class="chart-bar"><div class="chart-label">Temperature</div><div class="chart-bar-fill"><div class="chart-bar-value" style="width:60%">18°C ✅ Good</div></div></div></div><div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><p><strong>✅ Training Complete!</strong> You now know how to read digital sensors. These tools help scientists monitor water quality 24/7, detecting pollution before it becomes a crisis.</p></div><button class="btn btn-success" onclick="completeChapter()">Complete Training</button></div>'}
function loadGenericChallenge(c,n){const ch=ALL_CHAPTERS[n-1];c.innerHTML=`<div class="mini-game-container"><h4>Chapter ${n} Challenge</h4><p>This is a ${ch.difficulty}-star difficulty challenge!</p><div class="test-result good"><strong>Objective:</strong> ${ch.mission}</div><button class="btn btn-success" onclick="completeChapter()">Complete Challenge</button></div>`}
function completeChapter(){const c=ALL_CHAPTERS[gameState.currentChapter-1];gameState.ecoPoints+=c.rewards.ecoPoints;gameState.trustLevel+=c.rewards.trust;gameState.waterQuality+=2;gameState.completedChapters.push(gameState.currentChapter);c.rewards.items.forEach(i=>{if(!gameState.inventory.includes(i))gameState.inventory.push(i)});showAchievement('✅ Chapter Complete!',`You earned ${c.rewards.ecoPoints} Eco Points!`);updateStats();setTimeout(()=>{gameState.currentChapter++;if(gameState.currentChapter>ALL_CHAPTERS.length)showGameComplete();else loadChapter(gameState.currentChapter)},2000)}
function showAchievement(t,m){const p=document.createElement('div');p.className='achievement-popup';p.innerHTML=`<h3>${t}</h3><p>${m}</p>`;document.body.appendChild(p);setTimeout(()=>p.remove(),3000)}
function showHint(n){const hints={1:"Look for extreme pH and turbidity values!",2:"Diplomatic approaches build more trust.",3:"Digital sensors provide precise data.",default:"Balance science with community needs."};showAchievement('💡 Hint',hints[n]||hints.default)}
function updateInventory(){const g=document.getElementById('inventoryGrid');if(!g)return;const icons={'pH Strips':'🧪','Thermometer':'🌡️','Eco Journal':'📓','Field Notebook':'📔','Digital Probe':'📡','Drone':'🚁'};g.innerHTML=gameState.inventory.map(i=>`<div class="inventory-item unlocked"><div class="item-icon">${icons[i]||'🔧'}</div><div class="item-name">${i}</div></div>`).join('')}
function showGameComplete(){document.getElementById('gameContent').innerHTML='<div class="chapter-card"><h2 style="text-align:center;color:#1e3c72">🎉 Congratulations!</h2><div class="story-text"><p>You have completed all 30 chapters of Water Quality Quest!</p><p><strong>Final Stats:</strong></p><ul><li>Eco Points: '+gameState.ecoPoints+'</li><li>Trust Level: '+gameState.trustLevel+'</li><li>Water Quality: '+gameState.waterQuality+'%</li><li>Data Collected: '+gameState.dataCollected+'</li></ul><p>You are now a Master Eco Ranger! Your dedication to environmental science and community engagement has made a real difference in Aqualis Valley.</p></div><button class="btn btn-primary" onclick="initGame()">Play Again</button></div>';showAchievement('🏆 Master Ranger!','You completed all 30 chapters!')}

// Chapter 4: Mapping Game
function loadMappingGame(c){c.innerHTML='<div class="mini-game-container"><h4>🗺️ Drone Mapping Mission</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: How Pollution Travels Through Water Systems</h4><p><strong>Upstream vs. Downstream:</strong> Water flows downhill. Pollution from upstream spreads downstream, affecting everything below.</p><p><strong>Why map pollution flow:</strong> Finding where contamination is HIGHEST tells you where it started. Work backwards from the worst spot!</p></div><p><strong>Instructions:</strong> Click on the map to fly your drone and collect samples. Find the pollution source!</p><div class="sample-grid"><div class="sample-card" onclick="mapSample(\'upstream\',this)"><div class="icon">⬆️</div><div class="label">Upstream</div></div><div class="sample-card" onclick="mapSample(\'midstream\',this)"><div class="icon">➡️</div><div class="label">Midstream</div></div><div class="sample-card" onclick="mapSample(\'downstream\',this)"><div class="icon">⬇️</div><div class="label">Downstream</div></div><div class="sample-card" onclick="mapSample(\'tributary\',this)"><div class="icon">↗️</div><div class="label">Tributary</div></div></div><div id="mapResults"></div><button class="btn btn-success" onclick="completeChapter()">Complete Mapping</button></div>'}
function mapSample(loc,el){el.classList.add('selected');const results={upstream:'High pollution detected! (Source is nearby)',midstream:'Moderate contamination (pollution flowing through)',downstream:'Low pollution (diluted by distance)',tributary:'Clean water source (unaffected)'};const explanation={upstream:'🚨 Highest pollution = closest to source!',midstream:'Pollution decreases as it flows downstream',downstream:'Water dilutes pollution over distance',tributary:'Side streams can be clean if no local pollution'};document.getElementById('mapResults').innerHTML+=`<div class="test-result good"><strong>${loc.toUpperCase()}:</strong> ${results[loc]}<br><em style="font-size:12px;color:#555">${explanation[loc]}</em></div>`;gameState.dataCollected++;updateStats();if(loc==='upstream'){document.getElementById('mapResults').innerHTML+='<div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><p><strong>✅ Pollution Source Located!</strong> The upstream area has the highest contamination. This means the pollution source is nearby, before the water flows downstream and gets diluted.</p></div>'}}

// Chapter 5: Stealth Game
function loadStealthGame(c){c.innerHTML='<div class="mini-game-container"><h4>🕵️ Stealth Investigation</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Industrial Pollution & Environmental Laws</h4><p><strong>Illegal discharge:</strong> Factories must treat wastewater before releasing it. Dumping untreated chemicals is illegal and harms ecosystems.</p><p><strong>Why evidence matters:</strong> Photos and water samples prove violations. Without proof, polluters deny responsibility.</p><p><strong>Environmental laws:</strong> Clean Water Act (1972) makes it illegal to pollute waterways. Violators face fines and cleanup orders.</p></div><p><strong>Mission:</strong> Sneak past security and photograph the illegal discharge. Choose your path carefully!</p><div class="choice-buttons"><div class="choice-btn" onclick="stealthChoice(\'front\',false)"><strong>🚪 Front Gate:</strong> Direct but risky</div><div class="choice-btn" onclick="stealthChoice(\'side\',true)"><strong>🌳 Side Fence:</strong> Safer route</div><div class="choice-btn" onclick="stealthChoice(\'wait\',true)"><strong>⏰ Wait for Night:</strong> Patient approach</div></div><div id="stealthResult"></div></div>'}
function stealthChoice(path,success){if(success){document.getElementById('stealthResult').innerHTML='<div class="test-result good"><strong>✅ Success!</strong> You collected photo evidence and water samples without being detected!</div><div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><p><strong>Evidence Collected:</strong></p><ul style="text-align:left"><li>📸 Photos of illegal discharge pipe</li><li>🧪 Water samples showing high toxicity</li><li>📝 Documentation of violations</li></ul><p>This evidence can be used to hold the factory accountable and force them to stop polluting!</p></div><button class="btn btn-success" onclick="completeChapter()">Complete Mission</button>';gameState.dataCollected+=2}else{document.getElementById('stealthResult').innerHTML='<div class="test-result warning"><strong>⚠️ Detected!</strong> Security spotted you, but you got the evidence. Trust decreased.</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';gameState.trustLevel-=5}updateStats()}

// Chapter 6: Farming Simulator
function loadFarmingGame(c){c.innerHTML='<div class="mini-game-container"><h4>🚜 Sustainable Farming Simulator</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Nitrogen Cycles, Eutrophication & Farm Runoff</h4><p><strong>Fertilizers contain nitrogen:</strong> Plants need nitrogen to grow, but excess nitrogen washes into waterways.</p><p><strong>Eutrophication:</strong> Too much nitrogen → algae blooms → algae die → bacteria consume oxygen → fish suffocate!</p><p><strong>Sustainable farming:</strong> Use just enough fertilizer for crops. Excess = wasted money + water pollution.</p></div><p><strong>Goal:</strong> Choose fertilizer amount. Too little = poor crops. Too much = water pollution!</p><div class="chart-bar"><div class="chart-label">Fertilizer Amount (kg/hectare)</div><input type="range" id="fertSlider" min="0" max="100" value="50" oninput="updateFertPreview(this.value)" style="width:100%;margin:10px 0"></div><div id="fertPreview" style="padding:10px;background:#f0f0f0;border-radius:5px;margin:10px 0">Current: 50 units - Balanced approach</div><button class="btn btn-success" onclick="applyFertilizer()">Apply Fertilizer</button><div id="farmResult"></div></div>'}
function updateFertPreview(val){const msgs={low:'Too little - crops will suffer',balanced:'Perfect balance - sustainable farming!',high:'Too much - will pollute water!'};const msg=val<30?msgs.low:val>70?msgs.high:msgs.balanced;document.getElementById('fertPreview').innerHTML=`Current: ${val} units - ${msg}`}
function applyFertilizer(){const val=document.getElementById('fertSlider').value;if(val>=30&&val<=70){document.getElementById('farmResult').innerHTML='<div class="test-result good"><strong>🌾 Excellent!</strong> Crops thrive and water stays clean!</div><div class="learning-box" style="background:#d4edda;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #28a745"><p><strong>✅ Perfect Balance Achieved!</strong></p><p>You used <strong>'+val+' kg/hectare</strong> - the optimal amount. Crops get enough nitrogen to grow healthy, but there\'s no excess to run off into streams. This is sustainable farming!</p><p><strong>Result:</strong> High crop yield + Clean water = Win-win for farmers and environment!</p></div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';gameState.trustLevel+=20}else if(val<30){document.getElementById('farmResult').innerHTML='<div class="test-result warning"><strong>⚠️ Too Little Fertilizer!</strong> Crops are stunted and yellow (nitrogen deficiency). Farmer loses money from poor harvest.</div><div class="learning-box" style="background:#fff3cd;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #ffc107"><p>While this won\'t pollute water, it\'s not sustainable for the farmer\'s livelihood. We need solutions that work for BOTH people and environment.</p></div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';gameState.waterQuality-=5}else{document.getElementById('farmResult').innerHTML='<div class="test-result danger"><strong>🚨 Too Much Fertilizer!</strong> Excess nitrogen runs off into the stream during rain!</div><div class="learning-box" style="background:#ffebee;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #e74c3c"><p><strong>What happens next:</strong></p><ol style="text-align:left"><li>Nitrogen feeds algae → massive algae bloom (green water)</li><li>Algae die and sink to bottom</li><li>Bacteria decompose dead algae, consuming ALL oxygen</li><li>Fish suffocate in oxygen-depleted "dead zone"</li></ol><p>This is called <strong>eutrophication</strong> - one of the biggest water quality problems worldwide!</p></div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';gameState.waterQuality-=10}updateStats()}

// Chapter 7: Timed Challenge
let timerInterval;
function loadTimedChallenge(c){c.innerHTML='<div class="mini-game-container"><h4>⏱️ Storm Drain Emergency!</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Urban Runoff & Green Infrastructure</h4><p><strong>Urban runoff:</strong> Rain washes oil, trash, chemicals, and pet waste from streets into storm drains → directly to rivers (no treatment!).</p><p><strong>Combined sewer overflows (CSOs):</strong> In old cities, heavy rain overwhelms sewers, dumping raw sewage into waterways.</p><p><strong>Green infrastructure:</strong> Rain gardens, permeable pavement, and green roofs absorb water before it becomes polluted runoff.</p></div><p><strong>You have 60 seconds!</strong> Deploy barriers before pollution reaches the lake!</p><div id="timer" style="font-size:48px;text-align:center;color:#e74c3c;margin:20px 0">60</div><div class="sample-grid"><div class="sample-card" onclick="deployBarrier(this,\'north\')"><div class="icon">🚧</div><div class="label">North Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'south\')"><div class="icon">🚧</div><div class="label">South Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'east\')"><div class="icon">🚧</div><div class="label">East Drain</div></div><div class="sample-card" onclick="deployBarrier(this,\'west\')"><div class="icon">🚧</div><div class="label">West Drain</div></div></div><div id="timedResult"></div></div>';let timeLeft=60;timerInterval=setInterval(()=>{timeLeft--;document.getElementById('timer').textContent=timeLeft;if(timeLeft<=0){clearInterval(timerInterval);document.getElementById('timedResult').innerHTML='<div class="test-result warning"><strong>⏰ Time Up!</strong> Some pollution reached the lake.</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>'}},1000)}
let barriersDeployed=0;
function deployBarrier(el,loc){el.classList.add('selected');el.innerHTML='<div class="icon">✅</div><div class="label">'+loc+' Secured!</div>';barriersDeployed++;if(barriersDeployed>=3){clearInterval(timerInterval);document.getElementById('timedResult').innerHTML='<div class="test-result good"><strong>🎉 Success!</strong> All barriers deployed in time!</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';gameState.waterQuality+=5;updateStats()}}

// Chapter 8: Training Game
let trainedStudents=0;
function loadTrainingGame(c){c.innerHTML='<div class="mini-game-container"><h4>👨‍🏫 Citizen Science Training</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Citizen Science & Data Quality Control</h4><p><strong>Citizen science:</strong> Regular people collect scientific data, expanding research capacity 1000x! But data must be accurate.</p><p><strong>Quality control:</strong> Scientists review citizen data for errors. pH can\'t be 14.5 (max is 14), negative temps are impossible, etc.</p><p><strong>Why it matters:</strong> Bad data → wrong conclusions → ineffective solutions. Teaching citizens proper methods ensures reliable results.</p></div><p><strong>Review student test results:</strong> Approve correct tests, reject incorrect ones. (pH scale: 0-14)</p><div id="studentTests"></div></div>';showNextStudent()}
function showNextStudent(){const tests=[{name:'Emma',ph:7.2,correct:true},{name:'Carlos',ph:14.5,correct:false},{name:'Aisha',ph:6.8,correct:true}];if(trainedStudents>=tests.length){document.getElementById('studentTests').innerHTML+='<div class="test-result good"><strong>✅ Training Complete!</strong> All students certified!</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>';return}const t=tests[trainedStudents];document.getElementById('studentTests').innerHTML=`<div class="dialogue-box"><div class="dialogue-character"><div class="character-avatar">👤</div><div class="character-name">${t.name}</div></div><div class="dialogue-text">I measured pH: ${t.ph}</div><div class="choice-buttons"><div class="choice-btn" onclick="reviewTest(true,${t.correct})">✅ Approve</div><div class="choice-btn" onclick="reviewTest(false,${t.correct})">❌ Reject & Retrain</div></div></div>`}
function reviewTest(approved,wasCorrect){if((approved&&wasCorrect)||(!approved&&!wasCorrect)){trainedStudents++;showAchievement('✅ Good Teaching!','Correct evaluation!');showNextStudent()}else{showAchievement('❌ Review Needed','Check the data again');gameState.trustLevel-=5;updateStats()}}

// Chapter 9: Acid Rain Game
function loadAcidRainGame(c){c.innerHTML='<div class="mini-game-container"><h4>🌧️ Acid Rain Mapping</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Acid Rain & Long-Distance Pollution</h4><p><strong>What is acid rain:</strong> Sulfur dioxide (SO₂) and nitrogen oxides (NOx) from coal plants mix with water vapor → sulfuric/nitric acid → acidic rain (pH &lt; 5.6).</p><p><strong>Long-distance transport:</strong> Pollution travels 100s of miles downwind. A coal plant in one state causes acid rain in another!</p><p><strong>Ecological damage:</strong> Acid rain kills trees, acidifies lakes (pH &lt; 5 = no fish), dissolves limestone buildings.</p><p><strong>Normal rain pH:</strong> 5.6 (slightly acidic from CO₂). Healthy = 5.6-7.0. Acid rain = &lt; 5.0.</p></div><p><strong>Collect rain samples and trace the pollution source.</strong></p><div class="sample-grid"><div class="sample-card" onclick="rainSample(\'north\',4.2,this)"><div class="icon">☁️</div><div class="label">North (50mi)</div></div><div class="sample-card" onclick="rainSample(\'south\',6.8,this)"><div class="icon">☁️</div><div class="label">South (50mi)</div></div><div class="sample-card" onclick="rainSample(\'east\',5.1,this)"><div class="icon">☁️</div><div class="label">East (50mi)</div></div><div class="sample-card" onclick="rainSample(\'west\',7.0,this)"><div class="icon">☁️</div><div class="label">West (50mi)</div></div></div><div id="rainResults"></div></div>'}
let rainSamples=0;
function rainSample(dir,ph,el){el.classList.add('selected');el.innerHTML=`<div class="icon">✅</div><div class="label">${dir}: pH ${ph}</div>`;rainSamples++;if(rainSamples>=3){document.getElementById('rainResults').innerHTML='<div class="test-result danger"><strong>🏭 Source Found!</strong> Coal plant to the North is causing acid rain (pH 4.2)!</div><button class="btn btn-success" onclick="completeChapter()">Report Findings</button>';gameState.dataCollected+=3;updateStats()}}

// Chapter 10: Presentation Game
function loadPresentationGame(c){c.innerHTML='<div class="mini-game-container"><h4>📊 Council Presentation</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Data Visualization & Science Communication</h4><p><strong>Why visualization matters:</strong> Raw data is hard to understand. Charts turn numbers into stories that non-scientists can grasp.</p><p><strong>Choosing the right chart:</strong> Bar charts compare categories, line graphs show trends over time, pie charts show proportions. Wrong chart = confused audience!</p><p><strong>Communicating to decision-makers:</strong> Politicians need clear, visual evidence to justify spending taxpayer money. Good charts = action.</p></div><p><strong>Choose the best charts to convince the council:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="presentChart(\'bar\',true)"><strong>📊 Bar Chart:</strong> Show pollution levels by location</div><div class="choice-btn" onclick="presentChart(\'pie\',false)"><strong>🥧 Pie Chart:</strong> Show budget allocation</div><div class="choice-btn" onclick="presentChart(\'line\',true)"><strong>📈 Line Graph:</strong> Show pollution trend over time</div><div class="choice-btn" onclick="presentChart(\'table\',false)"><strong>📋 Data Table:</strong> Raw numbers</div></div><div id="presentResult"></div></div>'}
let chartsChosen=0;
function presentChart(type,effective){chartsChosen++;if(effective){document.getElementById('presentResult').innerHTML+=`<div class="test-result good"><strong>✅ Effective!</strong> The ${type} chart convinced the council!</div>`;gameState.trustLevel+=15}else{document.getElementById('presentResult').innerHTML+=`<div class="test-result warning"><strong>⚠️ Confusing!</strong> The ${type} chart didn't help your case.</div>`;gameState.trustLevel-=5}if(chartsChosen>=2){document.getElementById('presentResult').innerHTML+='<button class="btn btn-success" onclick="completeChapter()">End Presentation</button>'}updateStats()}

// Chapter 11: Strategy Game
function loadStrategyGame(c){c.innerHTML='<div class="mini-game-container"><h4>🌊 Strategic Decision</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Conservation Triage & Prioritization</h4><p><strong>Limited resources:</strong> We can\'t fix everything at once. Conservationists must prioritize based on urgency, impact, and feasibility.</p><p><strong>Triage decisions:</strong> Like emergency medicine - treat the most critical cases first, or save the most people? Both are valid strategies.</p><p><strong>Trade-offs:</strong> Fixing drinking water helps humans NOW. Removing microplastics protects ecosystems for 100 years. What\'s more important?</p></div><p><strong>Choose which tributary to restore first:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="chooseStrategy(\'north\',\'toxins\')"><strong>🏭 North Fork:</strong> High toxins, affects drinking water</div><div class="choice-btn" onclick="chooseStrategy(\'east\',\'nutrients\')"><strong>🚜 East Branch:</strong> Farm runoff, causes algae blooms</div><div class="choice-btn" onclick="chooseStrategy(\'south\',\'microplastics\')"><strong>♻️ South Stream:</strong> Microplastics, long-term ecosystem damage</div></div><div id="strategyResult"></div></div>'}
function chooseStrategy(location,issue){document.getElementById('strategyResult').innerHTML=`<div class="test-result good"><strong>Decision Made!</strong> You chose to address ${issue} in the ${location} tributary. This will have long-term consequences...</div><p style="margin:10px 0">💡 <strong>Lesson:</strong> In real conservation, we can't fix everything at once. Prioritization is crucial.</p><button class="btn btn-success" onclick="completeChapter()">Continue</button>`;gameState.decisions.push(location)}

// Chapter 12: Timeline Game
function loadTimelineGame(c){c.innerHTML='<div class="mini-game-container"><h4>📅 Historical Timeline</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Historical Analysis & Baseline Data</h4><p><strong>Why history matters:</strong> To know if water is getting worse, we need to know what "normal" was. Old photos, records, and stories establish baselines.</p><p><strong>Shifting baseline syndrome:</strong> Each generation accepts a more degraded environment as "normal." Your grandparents swam in rivers you wouldn\'t touch!</p><p><strong>Cause and effect:</strong> Timeline analysis reveals: Factory opens 1975 → First fish die-off 1990. That\'s a 15-year lag showing cumulative pollution.</p></div><p><strong>Match events to their impacts:</strong></p><div class="sample-grid"><div class="sample-card" onclick="timelineEvent(\'1960\',this)"><div class="icon">📸</div><div class="label">1960: Crystal Clear</div></div><div class="sample-card" onclick="timelineEvent(\'1975\',this)"><div class="icon">🏭</div><div class="label">1975: Factory Opens</div></div><div class="sample-card" onclick="timelineEvent(\'1990\',this)"><div class="icon">⚠️</div><div class="label">1990: First Fish Die-off</div></div><div class="sample-card" onclick="timelineEvent(\'2020\',this)"><div class="icon">🌊</div><div class="label">2020: Current Crisis</div></div></div><div id="timelineResult"></div><button class="btn btn-success" onclick="completeChapter()">Complete Analysis</button></div>'}
function timelineEvent(year,el){el.classList.add('selected');document.getElementById('timelineResult').innerHTML+=`<div class="test-result good"><strong>${year}:</strong> Event recorded in restoration plan</div>`;gameState.dataCollected++}

// Chapter 13: Mining Game
function loadMiningGame(c){c.innerHTML='<div class="mini-game-container"><h4>⛏️ Mine Exploration</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Heavy Metal Contamination & Acid Mine Drainage</h4><p><strong>Mining pollution:</strong> Abandoned mines leak heavy metals (lead, mercury, arsenic) for CENTURIES. Acid mine drainage turns streams orange and kills all life.</p><p><strong>Why it\'s dangerous:</strong> Heavy metals bioaccumulate in fish → humans eat fish → neurological damage, kidney failure, cancer.</p><p><strong>Cleanup challenges:</strong> Treating acid mine drainage costs millions per year, forever. Prevention is cheaper than cure!</p></div><p><strong>Collect samples at different depths. Watch your oxygen!</strong></p><div id="oxygenBar" style="background:#e74c3c;height:20px;width:100%;border-radius:10px;margin:10px 0"></div><div class="sample-grid"><div class="sample-card" onclick="mineSample(\'shallow\',10,this)"><div class="icon">🔸</div><div class="label">Shallow (10m)</div></div><div class="sample-card" onclick="mineSample(\'mid\',20,this)"><div class="icon">🔸</div><div class="label">Mid (50m)</div></div><div class="sample-card" onclick="mineSample(\'deep\',30,this)"><div class="icon">🔸</div><div class="label">Deep (100m)</div></div></div><div id="mineResults"></div></div>'}
let oxygenLevel=100;
function mineSample(depth,cost,el){oxygenLevel-=cost;document.getElementById('oxygenBar').style.width=oxygenLevel+'%';el.classList.add('selected');if(oxygenLevel<=0){document.getElementById('mineResults').innerHTML='<div class="test-result danger"><strong>⚠️ Low Oxygen!</strong> Returning to surface...</div><button class="btn btn-success" onclick="completeChapter()">Exit Mine</button>'}else{document.getElementById('mineResults').innerHTML+=`<div class="test-result good"><strong>${depth.toUpperCase()}:</strong> Heavy metal contamination detected</div>`;gameState.dataCollected++}}

// Chapter 14: Microscopy Game
function loadMicroscopyGame(c){c.innerHTML='<div class="mini-game-container"><h4>🔬 Microplastic Analysis</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Microplastics & Emerging Contaminants</h4><p><strong>What are microplastics:</strong> Plastic pieces &lt; 5mm. Come from washing synthetic clothes, tire wear, broken-down bottles. They\'re EVERYWHERE - even in rain!</p><p><strong>Why they\'re harmful:</strong> Fish mistake them for food → plastic fills stomach → starvation. Plastics also absorb toxins like a sponge, concentrating pollution.</p><p><strong>Washing machine connection:</strong> One load of laundry releases 700,000 microfibers into wastewater! Most pass through treatment plants into rivers.</p></div><p><strong>Count microplastics in each sample:</strong></p><div class="sample-grid"><div class="sample-card" onclick="countPlastics(250,this)"><div class="icon">💧</div><div class="label">Lake Water</div></div><div class="sample-card" onclick="countPlastics(180,this)"><div class="icon">🐟</div><div class="label">Fish Tissue</div></div><div class="sample-card" onclick="countPlastics(420,this)"><div class="icon">🧼</div><div class="label">Washing Machine Drain</div></div></div><div id="microResults"></div><button class="btn btn-success" onclick="completeChapter()">Complete Analysis</button></div>'}
function countPlastics(count,el){el.classList.add('selected');el.innerHTML+=`<div style="color:#e74c3c;font-weight:bold">${count} fibers/L</div>`;gameState.dataCollected++}

// Chapter 15: Crisis Game
function loadCrisisGame(c){c.innerHTML='<div class="mini-game-container"><h4>🚨 Algae Bloom Emergency!</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Algae Blooms, Hypoxia & Emergency Response</h4><p><strong>Harmful algae blooms (HABs):</strong> Excess nutrients → explosive algae growth → algae die → bacteria decompose algae, consuming ALL oxygen → fish suffocate in "dead zones."</p><p><strong>Speed matters:</strong> Hypoxia (low oxygen) kills fish in HOURS. Emergency oxygenators can save ecosystems if deployed fast enough.</p><p><strong>Prevention vs. response:</strong> Stopping nutrient pollution prevents blooms. But once a bloom starts, you must act immediately to save wildlife.</p></div><p><strong>Deploy emergency measures NOW!</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="crisisAction(\'oxygen\',true)"><strong>💨 Deploy Oxygenators:</strong> Save the fish!</div><div class="choice-btn" onclick="crisisAction(\'nutrients\',true)"><strong>🧪 Test Nutrients:</strong> Find the cause</div><div class="choice-btn" onclick="crisisAction(\'wait\',false)"><strong>⏰ Wait and Monitor:</strong> Observe first</div></div><div id="crisisResult"></div></div>'}
function crisisAction(action,effective){if(effective){document.getElementById('crisisResult').innerHTML=`<div class="test-result good"><strong>✅ Lives Saved!</strong> Your quick action prevented ecosystem collapse!</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>`;gameState.waterQuality+=10}else{document.getElementById('crisisResult').innerHTML=`<div class="test-result danger"><strong>❌ Too Slow!</strong> Many fish died while you waited.</div><button class="btn btn-success" onclick="completeChapter()">Continue</button>`;gameState.waterQuality-=10}updateStats()}

// Chapter 16: Well Testing Game
function loadWellTestingGame(c){c.innerHTML='<div class="mini-game-container"><h4>⛲ Well Contamination Mapping</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Groundwater Contamination & Aquifers</h4><p><strong>Groundwater vs. surface water:</strong> Groundwater is water stored underground in aquifers (rock layers). It supplies 50% of US drinking water!</p><p><strong>Contamination plumes:</strong> Pollutants seep down through soil, spreading underground like an invisible cloud. Mapping plumes shows where contamination is moving.</p><p><strong>Why depth matters:</strong> Shallow wells get contaminated first. Deep wells may stay clean if pollution hasn\'t reached that depth yet. Testing multiple depths maps the plume.</p></div><p><strong>Test wells at different depths to map the contamination plume:</strong></p><div class="sample-grid"><div class="sample-card" onclick="testWell(\'A\',5,this)"><div class="icon">⛲</div><div class="label">Well A (5m)</div></div><div class="sample-card" onclick="testWell(\'B\',15,this)"><div class="icon">⛲</div><div class="label">Well B (15m)</div></div><div class="sample-card" onclick="testWell(\'C\',25,this)"><div class="icon">⛲</div><div class="label">Well C (25m)</div></div><div class="sample-card" onclick="testWell(\'D\',35,this)"><div class="icon">⛲</div><div class="label">Well D (35m)</div></div></div><div id="wellResults"></div><button class="btn btn-success" onclick="completeChapter()">Complete Testing</button></div>'}
function testWell(well,depth,el){const status=depth<20?'contaminated':'safe';el.classList.add('selected');el.innerHTML+=`<div style="color:${status==='safe'?'#27ae60':'#e74c3c'}">${status.toUpperCase()}</div>`;gameState.dataCollected++}

// Chapter 17: Experiment Game
function loadExperimentGame(c){c.innerHTML='<div class="mini-game-container"><h4>🧪 Rain Collection Experiment</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Experimental Design & Scientific Method</h4><p><strong>Good science needs:</strong> 1) Control group (clean area for comparison), 2) Multiple samples (not just one!), 3) Repeated measurements (track changes over time).</p><p><strong>Why controls matter:</strong> Without a clean reference site, you can\'t prove pollution is abnormal. Maybe ALL rain is acidic naturally? (It\'s not, but you need to prove it!)</p><p><strong>Replication:</strong> One measurement could be a fluke. 30 days of data shows patterns and proves consistency.</p></div><p><strong>Design your 30-day experiment:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="experimentChoice(\'control\',true)"><strong>✅ Include Control:</strong> Collect from clean area</div><div class="choice-btn" onclick="experimentChoice(\'multiple\',true)"><strong>✅ Multiple Sites:</strong> Compare locations</div><div class="choice-btn" onclick="experimentChoice(\'daily\',true)"><strong>✅ Daily Samples:</strong> Track changes over time</div><div class="choice-btn" onclick="experimentChoice(\'single\',false)"><strong>❌ Single Sample:</strong> One-time measurement</div></div><div id="experimentResult"></div></div>'}
let experimentScore=0;
function experimentChoice(choice,good){if(good){experimentScore++;document.getElementById('experimentResult').innerHTML+=`<div class="test-result good"><strong>✅ Good Science!</strong> ${choice} added to protocol</div>`}else{document.getElementById('experimentResult').innerHTML+=`<div class="test-result warning"><strong>⚠️ Weak Design!</strong> ${choice} won't give reliable data</div>`}if(experimentScore>=2){document.getElementById('experimentResult').innerHTML+='<button class="btn btn-success" onclick="completeChapter()">Start Experiment</button>'}}

