function loadEcologyGame(c){c.innerHTML='<div class="mini-game-container"><h4>🦅 Food Web Analysis</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Biomagnification & Trophic Levels</h4><p><strong>Biomagnification:</strong> Toxins concentrate as they move UP the food chain. Algae (1x) → Insects (5x) → Fish (25x) → Eagles (125x)!</p><p><strong>Why top predators suffer most:</strong> Eagles eat hundreds of fish over their lifetime. Each fish contains toxins. Eagles accumulate ALL that pollution, reaching lethal levels.</p><p><strong>DDT case study:</strong> Pesticide DDT caused eagle eggs to have thin shells → eggs broke → eagles nearly extinct. Banning DDT saved them!</p></div><p><strong>Track contamination through the food chain:</strong></p><div class="sample-grid"><div class="sample-card" onclick="trackSpecies(\'algae\',1,this)"><div class="icon">🌿</div><div class="label">Algae (1x)</div></div><div class="sample-card" onclick="trackSpecies(\'insects\',5,this)"><div class="icon">🦗</div><div class="label">Insects (5x)</div></div><div class="sample-card" onclick="trackSpecies(\'fish\',25,this)"><div class="icon">🐟</div><div class="label">Fish (25x)</div></div><div class="sample-card" onclick="trackSpecies(\'birds\',125,this)"><div class="icon">🦅</div><div class="label">Birds (125x)</div></div></div><div id="ecologyResult"></div><button class="btn btn-success" onclick="completeChapter()">Complete Analysis</button></div>'}
function trackSpecies(species,bioaccumulation,el){el.classList.add('selected');el.innerHTML+=`<div style="color:#e74c3c;font-size:12px">Toxin: ${bioaccumulation}x</div>`;document.getElementById('ecologyResult').innerHTML=`<div class="test-result danger"><strong>⚠️ Biomagnification!</strong> Toxins concentrate ${bioaccumulation}x at this level!</div>`}

// Chapter 19: Emergency Response Game
function loadEmergencyGame(c){c.innerHTML='<div class="mini-game-container"><h4>🚨 Chemical Spill Emergency!</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Emergency Response Protocols & Incident Command</h4><p><strong>Chemical spill response:</strong> First: contain (stop spread), Second: alert (warn people), Third: monitor (track contamination), Fourth: document (evidence for prosecution).</p><p><strong>Incident Command System (ICS):</strong> Standardized emergency management used by fire, police, EPA. Clear chain of command saves lives.</p><p><strong>Why order matters:</strong> Alerting people BEFORE containing the spill causes panic. Containing FIRST gives you time to coordinate proper evacuation.</p></div><p><strong>Coordinate emergency response in real-time:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="emergencyStep(1)"><strong>1️⃣ Deploy Containment Booms</strong></div><div class="choice-btn" onclick="emergencyStep(2)"><strong>2️⃣ Alert Downstream Communities</strong></div><div class="choice-btn" onclick="emergencyStep(3)"><strong>3️⃣ Monitor Toxin Levels</strong></div><div class="choice-btn" onclick="emergencyStep(4)"><strong>4️⃣ Document Everything</strong></div></div><div id="emergencyProgress"></div></div>'}
