// Chapter 22: Engineering Game
function loadEngineeringGame(c){c.innerHTML='<div class="mini-game-container"><h4>⚙️ Bio-Filtration Engineering</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Water Treatment & Multi-Stage Filtration</h4><p><strong>How filtration works:</strong> Each layer removes different contaminants. Gravel (big particles) → Sand (small particles) → Bacteria (organic matter) → Carbon (chemicals).</p><p><strong>Biological filtration:</strong> Bacteria colonies eat organic pollutants, converting them to harmless CO₂ and water. Living filters!</p><p><strong>Activated carbon:</strong> Super porous charcoal absorbs chemicals like a sponge. One gram has surface area of a football field!</p></div><p><strong>Optimize your filter layers:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="addLayer(\'gravel\')"><strong>🪨 Gravel Layer:</strong> Physical filtration</div><div class="choice-btn" onclick="addLayer(\'sand\')"><strong>⏳ Sand Layer:</strong> Fine particle removal</div><div class="choice-btn" onclick="addLayer(\'bacteria\')"><strong>🦠 Bacterial Layer:</strong> Biological breakdown</div><div class="choice-btn" onclick="addLayer(\'carbon\')"><strong>⚫ Activated Carbon:</strong> Chemical absorption</div></div><div id="engineerResult"></div></div>'}
let layers=0;
function addLayer(type){layers++;document.getElementById('engineerResult').innerHTML+=`<div class="test-result good"><strong>Layer ${layers}:</strong> ${type} added to filter</div>`;if(layers>=3){document.getElementById('engineerResult').innerHTML+='<div class="test-result good"><strong>✅ Filter Complete!</strong> Multi-stage filtration system operational!</div><button class="btn btn-success" onclick="completeChapter()">Test System</button>';gameState.waterQuality+=15;updateStats()}}

// Chapter 23: Budget Game
function loadBudgetGame(c){c.innerHTML='<div class="mini-game-container"><h4>💰 Budget Allocation</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Environmental Economics & Cost-Benefit Analysis</h4><p><strong>Limited budgets:</strong> Environmental groups must prioritize. Sensors provide ongoing data. Education prevents future pollution. Legal action stops polluters. Restoration heals damage.</p><p><strong>Cost-benefit analysis:</strong> $40K in sensors generates $1M in evidence for lawsuits. Smart investment multiplies impact!</p><p><strong>Prevention vs. cleanup:</strong> Preventing pollution costs 10x less than cleaning it up. Education is the best long-term investment.</p></div><p><strong>You have $100,000. Allocate wisely!</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="allocateBudget(\'sensors\',40000)"><strong>📡 Sensors:</strong> $40,000</div><div class="choice-btn" onclick="allocateBudget(\'education\',30000)"><strong>📚 Education:</strong> $30,000</div><div class="choice-btn" onclick="allocateBudget(\'legal\',50000)"><strong>⚖️ Legal Action:</strong> $50,000</div><div class="choice-btn" onclick="allocateBudget(\'restoration\',60000)"><strong>🌿 Restoration:</strong> $60,000</div></div><div id="budgetResult"></div></div>'}
let totalBudget=100000;let spent=0;
function allocateBudget(item,cost){if(spent+cost<=totalBudget){spent+=cost;document.getElementById('budgetResult').innerHTML+=`<div class="test-result good"><strong>✅ ${item}:</strong> $${cost.toLocaleString()} allocated</div><p>Remaining: $${(totalBudget-spent).toLocaleString()}</p>`;if(spent>=80000){document.getElementById('budgetResult').innerHTML+='<button class="btn btn-success" onclick="completeChapter()">Finalize Budget</button>'}}else{document.getElementById('budgetResult').innerHTML+=`<div class="test-result danger"><strong>❌ Over Budget!</strong> Can't afford ${item}</div>`}}

// Chapter 24: Debate Game
function loadDebateGame(c){c.innerHTML='<div class="mini-game-container"><h4>⚖️ Legal Tribunal</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Environmental Law & Scientific Evidence in Court</h4><p><strong>Burden of proof:</strong> You must PROVE the factory caused pollution. Correlation isn\'t causation - need direct evidence linking discharge to contamination.</p><p><strong>Expert testimony:</strong> Scientists explain complex data to judges/juries. Dr. Chen\'s credentials make evidence credible.</p><p><strong>Emotional vs. scientific:</strong> Courts need DATA, not feelings. "Fish are dying" (emotional) vs. "pH 4.8 exceeds legal limit of 6.5" (scientific) = win.</p></div><p><strong>Defend your evidence against corporate lawyers:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="legalArgument(\'data\',true)"><strong>📊 Present Data:</strong> Show pollution measurements</div><div class="choice-btn" onclick="legalArgument(\'emotion\',false)"><strong>😢 Emotional Appeal:</strong> Talk about suffering</div><div class="choice-btn" onclick="legalArgument(\'causation\',true)"><strong>🔬 Prove Causation:</strong> Link factory to pollution</div><div class="choice-btn" onclick="legalArgument(\'expert\',true)"><strong>👨‍🔬 Expert Testimony:</strong> Call Dr. Chen</div></div><div id="debateResult"></div></div>'}
let legalPoints=0;
function legalArgument(arg,strong){if(strong){legalPoints++;document.getElementById('debateResult').innerHTML+=`<div class="test-result good"><strong>✅ Strong Argument!</strong> ${arg} accepted by court</div>`}else{document.getElementById('debateResult').innerHTML+=`<div class="test-result warning"><strong>⚠️ Weak Argument!</strong> ${arg} dismissed</div>`}if(legalPoints>=2){document.getElementById('debateResult').innerHTML+='<div class="test-result good"><strong>🎉 Case Won!</strong> Factory ordered to clean up!</div><button class="btn btn-success" onclick="completeChapter()">Victory!</button>';gameState.trustLevel+=40;updateStats()}}

