function loadEducationGame(c){c.innerHTML='<div class="mini-game-container"><h4>🎓 Festival Exhibit Design</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Science Communication & Public Engagement</h4><p><strong>Interactive learning:</strong> People remember 10% of what they read, 90% of what they DO. Hands-on exhibits teach better than lectures!</p><p><strong>Meeting people where they are:</strong> Festivals reach families who\'d never attend a science talk. Make learning fun = lasting impact.</p><p><strong>Inspiring next generation:</strong> One kid using a microscope today = future environmental scientist. Education creates change-makers.</p></div><p><strong>Create 5 interactive exhibits:</strong></p><div class="sample-grid"><div class="sample-card" onclick="createExhibit(\'testing\',this)"><div class="icon">🧪</div><div class="label">Water Testing Station</div></div><div class="sample-card" onclick="createExhibit(\'microscope\',this)"><div class="icon">🔬</div><div class="label">Microplastic Microscope</div></div><div class="sample-card" onclick="createExhibit(\'watershed\',this)"><div class="icon">🗺️</div><div class="label">Watershed Model</div></div><div class="sample-card" onclick="createExhibit(\'vr\',this)"><div class="icon">🥽</div><div class="label">VR River Tour</div></div><div class="sample-card" onclick="createExhibit(\'quiz\',this)"><div class="icon">🎯</div><div class="label">Eco Quiz Game</div></div></div><div id="exhibitResult"></div><button class="btn btn-success" onclick="completeChapter()">Open Festival</button></div>'}
