// Chapter 26: Satellite Game
function loadSatelliteGame(c){c.innerHTML='<div class="mini-game-container"><h4>🛰️ Satellite Analysis</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Remote Sensing & Global Environmental Monitoring</h4><p><strong>Satellites see the big picture:</strong> Thermal imaging detects hot wastewater discharge. Spectral analysis identifies algae blooms. Change detection tracks deforestation.</p><p><strong>Global monitoring:</strong> Satellites watch every river, lake, and ocean simultaneously. Impossible to hide pollution from space!</p><p><strong>Open data revolution:</strong> NASA/ESA satellite data is FREE for anyone. Citizen scientists can monitor their own watersheds from space!</p></div><p><strong>Analyze pollution from space:</strong></p><div class="sample-grid"><div class="sample-card" onclick="analyzeSatellite(\'thermal\',this)"><div class="icon">🌡️</div><div class="label">Thermal Imaging</div></div><div class="sample-card" onclick="analyzeSatellite(\'spectral\',this)"><div class="icon">🌈</div><div class="label">Spectral Analysis</div></div><div class="sample-card" onclick="analyzeSatellite(\'change\',this)"><div class="icon">📊</div><div class="label">Change Detection</div></div><div class="sample-card" onclick="analyzeSatellite(\'global\',this)"><div class="icon">🌍</div><div class="label">Global Patterns</div></div></div><div id="satelliteResult"></div><button class="btn btn-success" onclick="completeChapter()">Share Findings</button></div>'}
function analyzeSatellite(method,el){el.classList.add('selected');el.innerHTML+=`<div style="color:#3498db;font-size:12px">Analyzed</div>`;gameState.dataCollected+=5}

// Chapter 27: Drought Game
function loadDroughtGame(c){c.innerHTML='<div class="mini-game-container"><h4>🏜️ Drought Crisis Management</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Water Scarcity & Competing Demands</h4><p><strong>Water is finite:</strong> During drought, there\'s not enough for everyone. Humans need drinking water. Farms need irrigation. Rivers need flow for fish.</p><p><strong>Ethical dilemmas:</strong> Let crops die to save fish? Let fish die to save farms? No perfect answer - just difficult trade-offs.</p><p><strong>Climate change impact:</strong> Droughts are longer and more severe. Water management becomes THE critical challenge of 21st century.</p></div><p><strong>Allocate scarce water resources:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="allocateWater(\'drinking\',40)"><strong>🚰 Drinking Water:</strong> 40% to humans</div><div class="choice-btn" onclick="allocateWater(\'farming\',30)"><strong>🌾 Agriculture:</strong> 30% to farms</div><div class="choice-btn" onclick="allocateWater(\'ecosystem\',30)"><strong>🐟 Ecosystem:</strong> 30% to river</div></div><div id="droughtResult"></div></div>'}
let waterAllocated=0;
function allocateWater(use,percent){waterAllocated+=percent;document.getElementById('droughtResult').innerHTML+=`<div class="test-result good"><strong>${use}:</strong> ${percent}% allocated</div>`;if(waterAllocated>=90){document.getElementById('droughtResult').innerHTML+='<div class="test-result good"><strong>✅ Balanced Allocation!</strong> All needs considered</div><button class="btn btn-success" onclick="completeChapter()">Implement Plan</button>'}}

