function loadSummitGame(c){c.innerHTML='<div class="mini-game-container"><h4>🏛️ UN Global Summit</h4><div class="learning-box" style="background:#e3f2fd;padding:15px;border-radius:8px;margin:15px 0"><h4 style="margin-top:0">💡 Learning Goal: Policy Advocacy & Leadership</h4><p><strong>Speaking truth to power:</strong> World leaders control resources and laws. Your story can inspire policy change affecting millions!</p><p><strong>Effective messaging:</strong> Combine hope (change is possible) + urgency (act now) + evidence (science works) + empowerment (local action matters).</p><p><strong>Youth leadership:</strong> Greta Thunberg was 15 when she started. Young voices are powerful because you inherit the future we create today.</p></div><p><strong>Present to world leaders. Choose your key messages:</strong></p><div class="choice-buttons"><div class="choice-btn" onclick="summitMessage(\'local\')"><strong>🏘️ Local Action:</strong> Communities can solve problems</div><div class="choice-btn" onclick="summitMessage(\'science\')"><strong>🔬 Science Works:</strong> Data drives decisions</div><div class="choice-btn" onclick="summitMessage(\'hope\')"><strong>🌟 Hope Exists:</strong> Change is possible</div><div class="choice-btn" onclick="summitMessage(\'urgent\')"><strong>⏰ Urgency:</strong> Act now, not later</div></div><div id="summitResult"></div></div>'}
